# -- recording ------------------------------------------------------------------------------------------------------------------
def summary(value, depth=0):
    """A JSON-safe copy of a value Resolve returned or was given: API objects become their type name, never a call."""
    if value is None or isinstance(value, (bool, int, float, str)):
        return value
    if depth > 4:
        return "<%s>" % type(value).__name__
    if isinstance(value, (list, tuple)):
        return [summary(v, depth + 1) for v in value]
    if isinstance(value, dict):
        return dict((str(k), summary(v, depth + 1)) for k, v in value.items())
    return "<%s>" % type(value).__name__


def is_ok(call, value):
    if value is None or value is False:
        return False
    if call in ("MediaPool.ImportMedia", "MediaPool.AppendToTimeline"):
        return isinstance(value, (list, tuple)) and len(value) > 0 and all(v is not None for v in value)
    return True


class Recorder(object):
    """Makes every call to Resolve: checks it is documented, records it, never lets an exception escape."""

    def __init__(self, doc, gated):
        self.doc, self.gated = doc, gated  # gated: name -> True when the installed catalogue documents it

    def documented_in(self, name):
        if name in README_CALLS:
            return README
        if name in GATED_CALLS and self.gated.get(name.split(".")[-1]):
            return CATALOGUE
        return None

    def call(self, steps, where, obj, name, *args):
        """obj.<method>(*args) for name "Class.Method"; appends a step to ``steps`` (a list, or None for a quiet read) and returns the value."""
        doc_in = self.documented_in(name)
        step = {"call": name, "args": summary(list(args)), "documented_in": doc_in}
        if doc_in is None:
            step.update(called=False, ok=False, error=NOT_CALLED)
            if steps is not None:
                steps.append(step)
            return None
        try:
            value = getattr(obj, name.split(".")[-1])(*args)
        except Exception as exc:  # recorded, never raised: the probe moves on
            step.update(called=True, ok=False, error="%s: %s" % (type(exc).__name__, exc))
            self.fail(where, step)
            if steps is not None:
                steps.append(step)
            return None
        step.update(called=True, ok=is_ok(name, value), **{"return": summary(value)})
        if not step["ok"]:
            self.fail(where, step)
        if steps is not None:
            steps.append(step)
        return value

    def fail(self, where, step):
        entry = {"where": where}
        entry.update(step)
        self.doc["failures"].append(entry)


# -- timecode at the cut's rate -------------------------------------------------------------------------------------------------
def rate():
    return EXPECTED["rate"][0], EXPECTED["rate"][1]


def nominal():
    n, d = rate()
    return max(1, int(round(n / float(d))))


def is_drop_rate():
    n, d = rate()
    return d == 1001 and n in (30000, 60000)


def timecode_to_frames(text):
    """HH:MM:SS:FF (HH:MM:SS;FF drop-frame) -> (frames, drop); None when it is not a timecode."""
    m = re.match(r"^\s*(\d{1,3}):(\d{2}):(\d{2})([:;.,])(\d{2,3})\s*$", str(text or ""))
    if not m:
        return None
    h, mi, s, f = int(m.group(1)), int(m.group(2)), int(m.group(3)), int(m.group(5))
    drop = m.group(4) in ";," and is_drop_rate()
    n = nominal()
    total = ((h * 60 + mi) * 60 + s) * n + f
    if drop:
        minutes = 60 * h + mi
        total -= (2 if n == 30 else 4) * (minutes - minutes // 10)
    return total, drop


def frames_to_timecode(frames, drop):
    n = nominal()
    if drop:
        d = 2 if n == 30 else 4
        per_minute, per_ten = n * 60 - d, n * 600 - 9 * d
        tens, rest = divmod(frames, per_ten)
        frames += 9 * d * tens + (d * ((rest - d) // per_minute) if rest >= d else 0)
    seconds, f = divmod(frames, n)
    return "%02d:%02d:%02d%s%0*d" % (seconds // 3600, seconds // 60 % 60, seconds % 60, ";" if drop else ":", max(2, len(str(n - 1))), f)


def rate_setting():
    """The project frame rate setting for the cut's rate, as Resolve's project settings list them."""
    n, d = rate()
    return {(24000, 1001): "23.976", (30000, 1001): "29.97", (60000, 1001): "59.94"}.get((n, d), ("%d" % (n // d)) if n % d == 0 else "%.3f" % (n / float(d)))


# -- the environment ----------------------------------------------------------------------------------------------------------
def platform_key():
    return "darwin" if sys.platform == "darwin" else "win32" if sys.platform.startswith("win") else "linux"


def scripting_dirs():
    dirs = []
    if os.environ.get("RESOLVE_SCRIPT_API"):
        dirs.append(os.environ["RESOLVE_SCRIPT_API"])
    for d in SCRIPTING_DIRS[platform_key()]:
        if d not in dirs:
            dirs.append(d)
    return dirs


def sha256(path):
    try:
        with open(path, "rb") as fh:
            return hashlib.sha256(fh.read()).hexdigest()
    except (IOError, OSError):
        return None


def load_module(info):
    """Resolve's DaVinciResolveScript: already imported (sys.modules), importable as is, else from <RESOLVE_SCRIPT_API>/Modules or the default
    install folders. Records where it looked; None when it is nowhere."""
    lib = os.environ.get("RESOLVE_SCRIPT_LIB")
    default_lib = LIB_DEFAULTS[platform_key()]
    info.update(RESOLVE_SCRIPT_API=os.environ.get("RESOLVE_SCRIPT_API"), RESOLVE_SCRIPT_LIB=lib, lib_default=default_lib,
                lib_default_exists=os.path.isfile(default_lib), module_dirs_tried=[])
    if not lib and os.path.isfile(default_lib):
        os.environ["RESOLVE_SCRIPT_LIB"] = default_lib  # the module reads it to find fusionscript
        info["RESOLVE_SCRIPT_LIB_set_by_probe"] = default_lib
    mod = sys.modules.get("DaVinciResolveScript")
    candidates = [None] + [os.path.join(d, "Modules") for d in scripting_dirs()]
    for folder in candidates:
        if mod is not None:
            break
        if folder is not None:
            info["module_dirs_tried"].append(folder)
            if not os.path.isdir(folder):
                continue
            if folder not in sys.path:
                sys.path.append(folder)
        try:
            import DaVinciResolveScript as mod  # noqa: F811 (Resolve's own module)
        except ImportError:
            mod = None
        except BaseException as exc:  # the module exits when it cannot load fusionscript
            if isinstance(exc, KeyboardInterrupt):
                raise
            info["module_error"] = "%s: %s" % (type(exc).__name__, exc)
            mod = None
    info["module_found"] = mod is not None
    info["module_path"] = getattr(mod, "__file__", None) if mod is not None else None
    return mod


def find_catalogue():
    """The installed API catalogue (README.txt up to 21.0, README.md / DaVinciResolveScript.pyi since 21.1): paths, version lines, mentions."""
    files, texts = [], []
    for folder in scripting_dirs():
        for name in CATALOGUE_FILES:
            path = os.path.join(folder, name)
            if not os.path.isfile(path):
                continue
            try:
                with open(path, "r", encoding="utf-8", errors="replace") as fh:
                    text = fh.read()
            except (IOError, OSError) as exc:
                files.append({"path": path, "error": str(exc)})
                continue
            version = next((ln.strip() for ln in text.splitlines()[:80] if re.search(r"(?i)last updated|version\s*[:\d]", ln)), None)
            files.append({"path": path, "size": len(text), "version_line": version, "sha256": sha256(path)})
            texts.append(text)
        if files:
            break  # the first folder that has a catalogue is the install's
    names = sorted(set([n.split(".")[-1] for n in list(README_CALLS) + list(GATED_CALLS)] + list(LOOKED_UP)))
    mentions = dict((n, any(re.search(r"\b%s\b" % re.escape(n), t) for t in texts)) for n in names)
    excerpts = {}
    for n in [g.split(".")[-1] for g in GATED_CALLS] + list(LOOKED_UP):
        text = excerpt(texts, r"def\s+%s\b" % n) or excerpt(texts, r"\b%s\b" % n)  # a definition anywhere wins over a mention
        if text:
            # a type the signature names (AddTransition(self, options: TransitionOptions)) is excerpted too: its keys may be there
            for name in sorted(set(re.findall(r"\b([A-Z]\w*Options)\b", "\n".join(text.splitlines()[:5])))):
                more = excerpt(texts, r"class\s+%s\b" % name)
                if more:
                    text += "\n...\n" + more
            excerpts[n] = text[:4000]
    return {"found": bool(texts), "files": files, "mentions": mentions, "excerpts": excerpts,
            "gated": dict((g, mentions.get(g.split(".")[-1], False)) for g in GATED_CALLS)}


def excerpt(texts, pattern):
    """The lines around the first line matching ``pattern`` in any of ``texts`` (2 before, 30 after), or None."""
    for t in texts:
        lines = t.splitlines()
        hit = next((k for k, ln in enumerate(lines) if re.search(pattern, ln)), None)
        if hit is not None:
            return "\n".join(lines[max(0, hit - 2): hit + 30])[:3000]
    return None


def mcp_presence():
    paths = MCP_PATHS[platform_key()]
    found = [p for p in paths if os.path.exists(p)]
    return {"paths_checked": paths, "found": found, "observed": "file present" if found else "file absent", "documented": MCP_DOCUMENTED}


